from collections import deque
def transform_allhit(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    marks=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==1]
    hr=next((r for r,c in marks if c in (0,w-1)),None)
    vc=next((c for r,c in marks if r in (0,h-1)),None)
    seen=set()
    for r in range(h):
      for c in range(w):
       if grid[r][c]!=2 or (r,c) in seen: continue
       q=[(r,c)]; seen.add((r,c)); comp=[]
       while q:
        rr,cc=q.pop(); comp.append((rr,cc))
        for nr,nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
         if 0<=nr<h and 0<=nc<w and grid[nr][nc]==2 and (nr,nc) not in seen: seen.add((nr,nc));q.append((nr,nc))
       if (hr is not None and any(rr==hr for rr,cc in comp)) or (vc is not None and any(cc==vc for rr,cc in comp)):
        for rr,cc in comp: out[rr][cc]=1
    if hr is not None: out[hr]=[1]*w
    if vc is not None:
     for rr in range(h): out[rr][vc]=1
    return out
